# -*- coding: utf-8 -*-
"""
Verification of r124_dmf.py against the measured VLE data of
Xu et al., J. Chem. Eng. Data 2017, 62, 3414-3422 (Table 7).
Data below transcribed from the publisher PDF (T [K], x1, pexp [kPa]).
The shipped model uses its own Antoine psat (fit to the paper's
Table 5 REFPROP values), so its AARD can differ in the last digit
from the paper's reported 1.17 %.
"""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from r124_dmf import bubble_P, x_to_xi

DATA = [(303.15, 0.3467, 103.9), (303.15, 0.3908, 123.9), (303.15, 0.4658, 161.7), (303.15, 0.5542, 210.5), (303.15, 0.6627, 262.3), (303.15, 0.7631, 312.2), (313.15, 0.3096, 117.7), (313.15, 0.345, 135.1), (313.15, 0.3897, 165.1), (313.15, 0.4642, 217.1), (313.15, 0.5537, 272.0), (313.15, 0.6619, 337.1), (313.15, 0.7624, 420.4), (323.15, 0.245, 108.3), (323.15, 0.3077, 150.4), (323.15, 0.3425, 175.8), (323.15, 0.3878, 211.6), (323.15, 0.4631, 278.5), (323.15, 0.5531, 348.3), (323.15, 0.6612, 453.7), (323.15, 0.7618, 544.7), (333.15, 0.1924, 102.8), (333.15, 0.243, 137.5), (333.15, 0.3059, 197.8), (333.15, 0.3417, 225.1), (333.15, 0.3861, 271.6), (333.15, 0.4621, 360.6), (333.15, 0.5526, 441.6), (333.15, 0.6603, 573.6), (333.15, 0.7611, 689.2), (343.15, 0.1524, 103.1), (343.15, 0.1904, 136.0), (343.15, 0.2414, 180.6), (343.15, 0.3045, 252.1), (343.15, 0.3405, 288.9), (343.15, 0.3849, 344.3), (343.15, 0.4608, 450.5), (343.15, 0.5518, 555.2), (343.15, 0.6596, 725.6), (343.15, 0.7601, 844.5), (353.15, 0.1504, 133.8), (353.15, 0.189, 177.8), (353.15, 0.2405, 229.2), (353.15, 0.3037, 317.1), (353.15, 0.3387, 363.4), (353.15, 0.3835, 432.2), (353.15, 0.4591, 551.3), (353.15, 0.5511, 687.4), (353.15, 0.6588, 873.5), (353.15, 0.7591, 1061.0), (363.15, 0.1485, 174.3), (363.15, 0.1875, 228.1), (363.15, 0.2383, 294.1), (363.15, 0.3021, 393.1), (363.15, 0.3365, 451.2), (363.15, 0.3814, 532.6), (363.15, 0.4578, 673.5), (363.15, 0.5502, 841.7), (363.15, 0.6581, 1065.0), (363.15, 0.7582, 1269.0)]

devs = []
for T_K, x1, pexp_kPa in DATA:
    xi = x_to_xi(x1)
    pm = bubble_P(T_K - 273.15, xi) * 100.0   # bar -> kPa
    devs.append(abs(pm - pexp_kPa) / pexp_kPa * 100.0)
print("r124_dmf: n=%d  AARD=%.2f%%  MAX=%.2f%%" % (len(DATA), sum(devs)/len(devs), max(devs)))
